#define main original_hecbench_main
#include "../haccmk-cuda/haccmk.cu"
#undef main
#include <vector>
#include <cstring>
#include <cmath>
#include <chrono>
int main(int argc,char**argv){
const int n1=784,n2=15000,repeats=1;std::vector<float>input(4*n2),hx(n2),hy(n2),hz(n2),hm(n2);FILE*file=fopen("/home/imo/HeCBench_julia/src/haccmk-julia/study_input_f32.bin","rb");if(!file||fread(input.data(),4,4*n2,file)!=(size_t)4*n2)return 6;fclose(file);hx[0]=hy[0]=hz[0]=0;hm[0]=2;float dxstep=1.f/n2,dystep=2.f/n2,dzstep=3.f/n2;for(int i=1;i<n2;i++){hx[i]=hx[i-1]+dxstep;hy[i]=hy[i-1]+dystep;hz[i]=hz[i-1]+dzstep;volatile float product=float(i)*.01f;hm[i]=product+hx[i];}if(memcmp(hx.data(),input.data(),4*n2)||memcmp(hy.data(),input.data()+n2,4*n2)||memcmp(hz.data(),input.data()+2*n2,4*n2)||memcmp(hm.data(),input.data()+3*n2,4*n2))return 7;printf("STUDY_INPUT_NATIVE_RECURRENCE_BYTE_MATCH true\n");const float cut=.5f,soft=.03f,fc=.23f;const float cf[6]={.269327f,-.0750978f,.0114808f,-.00109313f,.0000605491f,-.00000147177f};std::vector<double>expected(3*n1);std::vector<float>gold(3*n1);for(int i=0;i<n1;i++){double ax=0,ay=0,az=0;for(int j=0;j<n2;j++){double dx=double(hx[j])-hx[i],dy=double(hy[j])-hy[i],dz=double(hz[j])-hz[i];double r2=dx*dx+dy*dy+dz*dz;double mass=r2<cut?hm[j]:0;double f=r2+soft,poly=cf[5];for(int k=4;k>=0;k--)poly=cf[k]+r2*poly;double force=mass*(1/(f*sqrt(f))-poly);ax+=force*dx;ay+=force*dy;az+=force*dz;}expected[i]=ax*fc;expected[n1+i]=ay*fc;expected[2*n1+i]=az*fc;float gx,gy,gz;haccmk_gold(n2,hx[i],hy[i],hz[i],cut,soft,hx.data(),hy.data(),hz.data(),hm.data(),&gx,&gy,&gz);gold[i]=gx*fc;gold[n1+i]=gy*fc;gold[2*n1+i]=gz*fc;}float*x,*y,*z,*mass,*vx,*vy,*vz;cudaMalloc(&x,n2*4);cudaMalloc(&y,n2*4);cudaMalloc(&z,n2*4);cudaMalloc(&mass,n2*4);cudaMalloc(&vx,n1*4);cudaMalloc(&vy,n1*4);cudaMalloc(&vz,n1*4);cudaMemcpy(x,hx.data(),n2*4,cudaMemcpyHostToDevice);cudaMemcpy(y,hy.data(),n2*4,cudaMemcpyHostToDevice);cudaMemcpy(z,hz.data(),n2*4,cudaMemcpyHostToDevice);cudaMemcpy(mass,hm.data(),n2*4,cudaMemcpyHostToDevice);cudaMemset(vx,0,n1*4);cudaMemset(vy,0,n1*4);cudaMemset(vz,0,n1*4);
 auto launch=[&](){haccmk_kernel<<<4,256>>>(n1,n2,x,y,z,mass,vx,vy,vz,cut,soft,fc);};launch();if(cudaDeviceSynchronize()!=cudaSuccess)return 4;
 bool allok=true;for(int trial=1;trial<=5;trial++){
 cudaMemset(vx,0,n1*4);cudaMemset(vy,0,n1*4);cudaMemset(vz,0,n1*4);cudaDeviceSynchronize();auto start=std::chrono::steady_clock::now();for(int j=0;j<repeats;j++)launch();auto status=cudaDeviceSynchronize();double seconds=std::chrono::duration<double>(std::chrono::steady_clock::now()-start).count()/repeats;
 std::vector<float>got(3*n1);cudaMemcpy(got.data(),vx,n1*4,cudaMemcpyDeviceToHost);cudaMemcpy(got.data()+n1,vy,n1*4,cudaMemcpyDeviceToHost);cudaMemcpy(got.data()+2*n1,vz,n1*4,cudaMemcpyDeviceToHost);double independent_relative=0;for(int i=0;i<3*n1;i++){if(!std::isfinite(got[i])||fabs(double(got[i])-gold[i])>1)return 8;independent_relative=fmax(independent_relative,fabs(double(got[i])-expected[i])/fmax(fabs(expected[i]),1.));}printf("STUDY_RELATIVE_FLOAT64_ERROR %.12g\n",independent_relative);if(independent_relative>1e-4)return 9;
 bool ok=status==cudaSuccess;double error=0,relative=0;for(size_t j=0;j<got.size();j++){double e=fabs((double)got[j]-expected[j]);error=fmax(error,e);relative=fmax(relative,e/fmax(fabs((double)expected[j]),1));ok&=std::isfinite((double)got[j])&&e<=1;}allok&=ok;
 char filename[80];snprintf(filename,sizeof(filename),"output_trial%d.bin",trial);FILE*f=fopen(filename,"wb");if(!f)return 5;fwrite(got.data(),sizeof(float),got.size(),f);fclose(f);
 printf("STUDY_TRIAL {\"trial\":%d,\"time_seconds\":%.12g,\"correct\":%s,\"checked_values\":%zu,\"max_abs_error\":%.12g,\"max_rel_error\":%.12g,\"timing_region\":\"kernel_launch_loop_per_internal_repeat\",\"jit_excluded\":true,\"internal_repeats\":%d,\"output_artifact\":{\"path\":\"%s\",\"dtype\":\"float32\",\"count\":%zu,\"byte_order\":\"little\"}}\n",trial,seconds,ok?"true":"false",got.size(),error,relative,repeats,filename,got.size());
 }return allok?0:1;
}
